output_text:
[
  {
    "id": "must_take_cart_from_entrance",
    "text": "Shoppers must check out and take the entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "has_shopping_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "must_return_cart_to_nw_bay_before_exit",
    "text": "Before leaving the supermarket, shoppers must return the cart to the northwest cart bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "nw_cart_return_bay": "at(0,1)",
        "cart_returned_to_nw_bay": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_nw_bay": {
          "pre": {
            "and": [
              "nw_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_to_nw_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_nw_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are prohibited from exiting the store while still holding or pushing a shopping cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "at_exit_door": "at(9,5)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "with_cart"
        ]
      }
    }
  },
  {
    "id": "no_abandon_cart_outside_return_bay",
    "text": "Shoppers may put a cart down only at the designated northwest cart-return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "outside_cart_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "leave_cart_somewhere": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_somewhere",
          "outside_cart_return_bay"
        ]
      }
    }
  },
  {
    "id": "items_must_be_collected_with_cart",
    "text": "Items should be picked up only while the shopper has a cart, rather than by hand alone.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        },
        "carrying_by_hand": "handFull"
      },
      "events": {
        "collect_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "collect_item",
          "without_cart"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers are prohibited from carrying merchandise by hand during the trip.",
    "abstraction": {
      "state_properties": {
        "hand_carrying_item": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_carrying_item"
    }
  },
  {
    "id": "after_collecting_item_return_cart",
    "text": "After any item is collected, the shopper must eventually return the cart to the northwest cart bay before exiting.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return_bay": "at(0,1)",
        "cart_parked_in_nw_bay": "cartAt(0,1)"
      },
      "events": {
        "collect_item_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "return_cart_to_nw_bay": {
          "pre": {
            "and": [
              "nw_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_nw_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_item_with_cart",
      "discharge": "return_cart_to_nw_bay"
    }
  },
  {
    "id": "after_cart_return_go_to_exit_without_cart",
    "text": "Once the cart has been returned, the shopper must proceed to the east exit without taking the cart again.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)",
        "east_exit": "at(9,5)",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cart_return_event": {
          "pre": {
            "and": [
              "at(0,1)",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned"
        },
        "exit_without_cart": {
          "pre": {
            "and": [
              "east_exit",
              "without_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_return_event",
      "discharge": "exit_without_cart"
    }
  }
]
